def load_skills(workspace: Path) -> dict[str, Skill]:
    skills: dict[str, Skill] = {}
    for path in sorted(Path(workspace, "skills").glob("*/SKILL.md")):
        meta, body = frontmatter(path.read_text())
        name = meta.get("name") or path.parent.name
        skills[name] = Skill(name, meta.get("description", ""), body)
    return skills


def workspace_of(toolkit: object) -> Path:
    """The directory of the module that defines the toolkit class: the workspace."""
    return Path(inspect.getfile(type(toolkit))).resolve().parent


class SkillTools:
    """Mix into `Tools` to give the model a `load_skill` tool over `workspace/skills/`."""

    @is_tool(ToolType.READ)
    def load_skill(self, name: str) -> JsonObject:
        """Load the full steps of one skill listed in your instructions.

        Args:
            name: The skill's name.
        """
        skills = load_skills(workspace_of(self))
        if name not in skills:
            raise ValueError(f"unknown skill {name!r}; available: {sorted(skills)}")
        return {"name": name, "steps": skills[name].body}
"""Load Markdown subagents and run them through the shared model and tool runtime."""
from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path

from .agent_context import ModelGateway
from .hooks import ToolRunner
from .messages import AssistantMessage, Message, MultiToolMessage, SystemMessage, UserMessage
from .skills import frontmatter, workspace_of
from .toolkit import Tool, ToolType, is_tool


@dataclass(frozen=True)
class Subagent:
    name: str
    description: str
    prompt: str
    model: str | None
    tools: tuple[str, ...]
    max_turns: int


def load_subagents(workspace: Path) -> dict[str, Subagent]:
    subagents: dict[str, Subagent] = {}
    for path in sorted(Path(workspace, "subagents").glob("*.md")):
        meta, body = frontmatter(path.read_text())
        name = meta.get("name") or path.stem
        tools = tuple(t.strip() for t in meta.get("tools", "").split(",") if t.strip())
        subagents[name] = Subagent(name, meta.get("description", ""), body, meta.get("model"),
                                   tools, int(meta.get("max_turns", 8)))
    return subagents


def run_subagent(spec: Subagent, task: str, gateway: ModelGateway, runner: ToolRunner) -> str:
    """Loop the subagent's model and tools until it answers with text."""
    tools = _allowed_tools(spec, runner)
    messages: list[Message] = [SystemMessage(spec.prompt), UserMessage(content=task)]
    for _ in range(spec.max_turns):
        reply = _next_reply(spec, gateway, messages, tools)
        messages.append(reply)
        if not reply.is_tool_call():
            return reply.content or ""
        messages.append(MultiToolMessage([runner.run(call) for call in reply.tool_calls or []]))
    raise RuntimeError(f"subagent {spec.name} did not answer within {spec.max_turns} turns")


def _allowed_tools(spec: Subagent, runner: ToolRunner) -> list[Tool]:
    return [tool for tool in runner.toolkit.get_tools() if tool.name in spec.tools]


def _next_reply(
    spec: Subagent,
    gateway: ModelGateway,
    messages: list[Message],
    tools: list[Tool],
) -> AssistantMessage:
    model = spec.model or gateway.models[0].model
    return gateway.generate(model=model, messages=messages, actions=tools or None)


class SubagentTools:
    """Mix into `Tools` to give the model a `delegate` tool over `workspace/subagents/`.

    The runtime sets `self.gateway` and `self.runner` before any tool runs.
    """

    gateway: ModelGateway
    runner: ToolRunner

    @is_tool(ToolType.GENERIC)
    def delegate(self, subagent: str, task: str) -> dict[str, str]:
        """Hand a self-contained task to a specialist subagent and get its answer.

        Args:
            subagent: Name of a subagent listed in your instructions.
            task: Everything the subagent needs; it sees nothing else of the conversation.
        """
        subagents = load_subagents(workspace_of(self))
        if subagent not in subagents:
            raise ValueError(f"unknown subagent {subagent!r}; available: {sorted(subagents)}")
        return {"subagent": subagent, "answer": run_subagent(subagents[subagent], task, self.gateway, self.runner)}
"""Hook declarations connect workspace callbacks to message and tool execution.

The runtime, not the agent, fires them, so they hold for every tool call,
including those a subagent makes.
"""
from __future__ import annotations

import inspect
import json
from collections.abc import Callable
from dataclasses import dataclass
from enum import StrEnum
from fnmatch import fnmatch
from types import MethodType
from typing import TYPE_CHECKING, Protocol, runtime_checkable

from .jsontypes import JsonObject, is_json_object
from .messages import ToolCall, ToolMessage

if TYPE_CHECKING:
    from .toolkit import ToolKitBase


class HookEvent(StrEnum):
    USER_MESSAGE = "user_message"
    PRE_TOOL = "pre_tool"
    POST_TOOL = "post_tool"


EVENTS = tuple(event.value for event in HookEvent)


@dataclass(frozen=True)
class HookBinding:
    event: HookEvent
    match: str


_HOOKS: dict[object, HookBinding] = {}


@runtime_checkable
class _UserMessageHook(Protocol):
    def __call__(self, text: str) -> object: ...


@runtime_checkable
class _PreToolHook(Protocol):
    def __call__(self, tool: str, arguments: JsonObject) -> object: ...


@runtime_checkable
class _PostToolHook(Protocol):
    def __call__(self, tool: str, arguments: JsonObject, result: object) -> object: ...


class Blocked(Exception):
    """Raise from a pre_tool hook to refuse the call; the message goes back to the model."""


def hook[F](event: str, match: str = "*") -> Callable[[F], F]:
    """Run the method on `event`; tool events only for tool names matching the `match` glob.

    user_message(self, text) -> str | None   replacement text, or None to keep it
    pre_tool(self, tool, args) -> dict | None  replacement arguments; raise Blocked to refuse
    post_tool(self, tool, args, result) -> object | None  replacement result
    """
    if event not in EVENTS:
        raise ValueError(f"unknown hook event {event!r}; use one of {EVENTS}")

    def decorate(function: F) -> F:
        _HOOKS[function] = HookBinding(HookEvent(event), match)
        return function

    return decorate


class HookKitBase:
    """Anything with `@hook` methods. Hooks for one event run in method-name order."""

    def hooks(self, event: str, tool: str = "") -> list[MethodType]:
        handlers: list[MethodType] = []
        for _, member in inspect.getmembers(self, inspect.ismethod):
            binding = _HOOKS.get(member.__func__)
            if binding is not None and binding.event == event and fnmatch(tool, binding.match):
                handlers.append(member)
        return handlers


class ToolRunner:
    """Runs tool calls through pre_tool and post_tool hooks. Every tool call goes through here."""

    def __init__(self, toolkit: ToolKitBase, hooks: HookKitBase | None = None) -> None:
        self.toolkit = toolkit
        self._hooks = hooks or HookKitBase()

    def user_message(self, text: str) -> str:
        for handler in self._hooks.hooks(HookEvent.USER_MESSAGE):
            if not isinstance(handler, _UserMessageHook):
                raise TypeError(f"{handler.__name__} is not a user_message hook")
            if (replaced := handler(text)) is not None:
                if not isinstance(replaced, str):
                    raise TypeError(f"{handler.__name__} must return a string or None")
                text = replaced
        return text

    def run(self, call: ToolCall) -> ToolMessage:
        try:  # a failing tool or hook is data for the agent, not a crash
            args = dict(call.arguments)
            for handler in self._hooks.hooks(HookEvent.PRE_TOOL, call.name):
                if not isinstance(handler, _PreToolHook):
                    raise TypeError(f"{handler.__name__} is not a pre_tool hook")
                if (replaced := handler(call.name, args)) is not None:
                    if not is_json_object(replaced):
                        raise TypeError(f"{handler.__name__} must return an object or None")
                    args = replaced
            result = self.toolkit.call(call.name, **args)
            for handler in self._hooks.hooks(HookEvent.POST_TOOL, call.name):
                if not isinstance(handler, _PostToolHook):
                    raise TypeError(f"{handler.__name__} is not a post_tool hook")
                if (replaced := handler(call.name, args, result)) is not None:
                    result = replaced
            return ToolMessage(call.id, json.dumps(result, default=str))
        except Blocked as error:
            return ToolMessage(call.id, f"Blocked: {error}", error=True)
        except Exception as error:
            return ToolMessage(call.id, f"Error: {error}", error=True)
"""Tool declarations connect workspace methods to the runtime's JSON tool interface."""
from __future__ import annotations

import inspect
import re
from collections.abc import Callable
from dataclasses import dataclass
from enum import StrEnum
from typing import TYPE_CHECKING, get_type_hints

from pydantic import create_model

from .jsontypes import Json, JsonObject, is_json_object

if TYPE_CHECKING:
    from .agent_context import ModelGateway
    from .billing import Billing
    from .developer import Developer
    from .hooks import ToolRunner


class ToolType(StrEnum):
    READ = "read"
    WRITE = "write"
    THINK = "think"
    GENERIC = "generic"


_TOOL_TYPES: dict[object, ToolType] = {}


def is_tool[**P](tool_type: ToolType = ToolType.READ) -> Callable[[Callable[P, object]], Callable[P, object]]:
    def decorate(function: Callable[P, object]) -> Callable[P, object]:
        _TOOL_TYPES[function] = tool_type
        return function

    return decorate


@dataclass(frozen=True)
class Tool:
    name: str
    description: str
    parameters: JsonObject

    @property
    def openai_schema(self) -> JsonObject:
        return {"type": "function", "name": self.name, "description": self.description, "parameters": self.parameters}


def _docstring_parts(doc: str | None) -> tuple[str, dict[str, str]]:
    """Split a Google-style docstring into (description, {arg: description})."""
    head, _, tail = inspect.cleandoc(doc or "").partition("Args:")
    tail = re.split(r"\n\s*(?:Returns|Raises|Examples?):", tail)[0]
    args: dict[str, str] = {}
    current: str | None = None
    for line in tail.splitlines():
        match = re.match(r"\s*(\w+)(?:\s*\([^)]*\))?:\s*(.*)", line)
        if match:
            current = match.group(1)
            args[current] = match.group(2).strip()
        elif current is not None and line.strip():
            args[current] += " " + line.strip()
    return " ".join(head.split()), args


def tool_from_method[**P](method: Callable[P, object]) -> Tool:
    description, arg_docs = _docstring_parts(method.__doc__)
    hints: dict[str, object] = get_type_hints(method)
    fields: dict[str, tuple[object, object]] = {}
    for name, parameter in inspect.signature(method).parameters.items():
        if name == "self":
            continue
        annotation = hints.get(name, object)
        default: object = ...
        if parameter.default is not inspect.Parameter.empty:
            default = parameter.default
        fields[name] = (annotation, default)
    schema_value: object = create_model(
        method.__name__,
        __config__=None,
        __doc__=None,
        __base__=None,
        __module__=__name__,
        __validators__=None,
        __cls_kwargs__=None,
        __qualname__=None,
        **fields,
    ).model_json_schema()
    if not is_json_object(schema_value):
        raise TypeError(f"tool schema for {method.__name__} must be a JSON object")
    schema = schema_value
    for name, text in arg_docs.items():
        properties = schema.get("properties")
        if not is_json_object(properties):
            continue
        parameter_schema = properties.get(name)
        if is_json_object(parameter_schema):
            parameter_schema["description"] = text
    schema.pop("title", None)
    return Tool(method.__name__, description, schema)


class ToolKitBase:
    """Anything with `@is_tool` methods; `get_tools()` lists them, `call()` runs one.

    The runtime sets `gateway` (ModelGateway), `runner`, `billing`, and `developer` before any tool runs.
    """

    gateway: ModelGateway
    runner: ToolRunner
    billing: Billing | None = None
    developer: Developer | None = None

    def get_tools(self) -> list[Tool]:
        tools = []
        for _, member in inspect.getmembers(self, inspect.ismethod):
            if member.__func__ in _TOOL_TYPES:
                tools.append(tool_from_method(member))
        return tools

    def call(self, name: str, /, **arguments: Json) -> object:
        for _, method in inspect.getmembers(self, inspect.ismethod):
            if method.__name__ == name and method.__func__ in _TOOL_TYPES:
                return method(**arguments)
        raise ValueError(f"Tool {name} not found")
