cd /app/R/sources; for f in fireflies/customer-success/2027-03-29-finance-x-support-sync-credit-ledger-cutover.json fireflies/customer-success/2027-03-10-finance-x-support-sync-march.json confluence/finance-and-legal/billing-controls/payment-failures-during-processor-incidents.json confluence/security-and-compliance/data-residency-and-retention/payment-card-data-handling-standard-2027.json confluence/finance-and-legal/revrec-and-billing/marketplace-revrec-and-invoicing-notes.json confluence/finance-and-legal/billing-controls/marketplace-credit-memo-limits-2027.json; do python3 -c "
import json;d=json.load(open('$f'));print('#####','$f',d.get('status'),d.get('last_updated') or d.get('recorded_at'))
for k in ('body','content','transcript','summary','notes','action_items'):
    if d.get(k): print(json.dumps(d[k],ensure_ascii=False)[:4000] if not isinstance(d[k],str) else d[k][:4000])"; done; grep -rl "2027-03-30\|priority" slack/support | xargs grep -l "Dev Patel" | xargs grep -l "urgent" | head

cd /app/R/sources; python3 -c "
import json;d=json.load(open('linear/engineering/ENG-9120-usage-pipeline-hourly-batch-cutover.json'));print(json.dumps(d,ensure_ascii=False,indent=0)[:3000])"; grep -rl '"urgent"\|urgent' slack | xargs grep -l "2027\|1774\|1775" 2>/dev/null | head; python3 - <<'EOF'
import json,glob,datetime
for f in glob.glob('slack/**/*.json',recursive=True):
    d=json.load(open(f))
    try: ts=float(d.get('thread_ts',0))
    except: continue
    dt=datetime.datetime.utcfromtimestamp(ts) if ts<4e9 else None
    if dt and dt.year==2027: print(dt.date(), f, len(json.dumps(d)))
EOF

cd /tmp/wb; python3 -c "
from redwood_kit.billing import development_billing, BillingError
b=development_billing()
for a in ['practice-ironbark','practice-juniper','practice-kestrel','practice-larchmont','practice-alderwick']:
  print('=====',a, b.query('accounts',{'account_id':a})['rows'])
  for t in ['contracts','invoices','usage','credit_grants','credit_ledger']:
    for x in b.query(t,{'account_id':a})['rows']: print(t,x)
for inv in ['PRACTICE-R1-DUP-60','PRACTICE-DUP-180']:
  for l in b.query('invoice_lines',{'invoice_id':inv})['rows']: print(l)
for t,w in [('credit_notes',{'account_id':'practice-alderwick'}),('credit_notes',{'billing_account_id':'practice-alderwick'}),('cases',{'account_id':'practice-alderwick'}),('cases',{'billing_account_id':'practice-alderwick'}),('disputes',{'billing_account_id':'practice-alderwick'})]:
  try: print(t,w,b.query(t,w))
  except BillingError as e: print(t,w,'ERR',e)
"

